     1|/**
     2| * IVX Twilio / SignalWire SMS sender — fallback/alternative to AWS SNS for owner notifications.
     3| *
     4| * Supports Twilio native API and SignalWire-compatible (Twilio API-compatible) hosts.
     5| *
     6| * Credentials modes:
     7| *   - Twilio Auth Token: IVX_TWILIO_ACCOUNT_SID + IVX_TWILIO_AUTH_TOKEN
     8| *   - Twilio API Key: IVX_TWILIO_ACCOUNT_SID + IVX_TWILIO_API_KEY_SID + IVX_TWILIO_API_KEY_SECRET
     9| *   - SignalWire: IVX_TWILIO_ACCOUNT_SID (Project ID) + IVX_TWILIO_AUTH_TOKEN (API token) + IVX_TWILIO_API_HOST=ivxholding.signalwire.com
    10| *   - IVX_TWILIO_MESSAGING_SERVICE_SID (preferred — uses the ivxholding.com service)
    11| *   - IVX_TWILIO_FROM_PHONE (fallback if no messaging service configured)
    12| *
    13| * Marker: ivx-twilio-sms-2026-08-12
    14| */
    15|
    16|import { normalizePhoneToE164 } from './ivx-sns-sms';
    17|
    18|export type TwilioSmsResult = {
    19|  ok: boolean;
    20|  status: 'sent' | 'missing_config' | 'rate_limited' | 'failed';
    21|  messageId?: string;
    22|  httpStatus?: number;
    23|  to?: string;
    24|  from?: string;
    25|  missingEnvNames: string[];
    26|  error?: string;
    27|  sentAt: string;
    28|  provider?: 'twilio' | 'signalwire';
    29|};
    30|
    31|function readEnv(name: string): string {
    32|  const v = process.env[name];
    33|  return typeof v === 'string' ? v.trim() : '';
    34|}
    35|
    36|/** True when Twilio or SignalWire has enough config to attempt a send. */
    37|export function isTwilioSmsConfigured(): boolean {
    38|  const accountSid = readEnv('IVX_TWILIO_ACCOUNT_SID');
    39|  const authToken = readEnv('IVX_TWILIO_AUTH_TOKEN');
    40|  const apiKeySid = readEnv('IVX_TWILIO_API_KEY_SID');
    41|  const apiKeySecret = readEnv('IVX_TWILIO_API_KEY_SECRET');
    42|  const authMode = Boolean(accountSid && authToken);
    43|  const keyMode = Boolean(accountSid && apiKeySid && apiKeySecret);
    44|  return authMode || keyMode;
    45|}
    46|
    47|function resolveApiHost(): { host: string; provider: 'twilio' | 'signalwire' } {
    48|  const customHost = readEnv('IVX_TWILIO_API_HOST');
    49|  if (customHost) {
    50|    const normalized = customHost.replace(/^https?:\/\//, '').replace(/\/$/, '');
    51|    return {
    52|      host: `https://${normalized}`,
    53|      provider: normalized.toLowerCase().endsWith('signalwire.com') ? 'signalwire' : 'twilio',
    54|    };
    55|  }
    56|  return { host: 'https://api.twilio.com', provider: 'twilio' };
    57|}
    58|
    59|function resolveFrom(): { messagingServiceSid?: string; fromPhone?: string } {
    60|  const messagingServiceSid = readEnv('IVX_TWILIO_MESSAGING_SERVICE_SID');
    61|  const fromPhone = normalizePhoneToE164(readEnv('IVX_TWILIO_FROM_PHONE'));
    62|  return messagingServiceSid ? { messagingServiceSid } : { fromPhone };
    63|}
    64|
    65|/**
    66| * Send a single SMS via Twilio Messaging API.
    67| * Returns structured status; never throws.
    68| */
    69|export async function sendTwilioSms(input: {
    70|  to: string;
    71|  message: string;
    72|}): Promise<TwilioSmsResult> {
    73|  const sentAt = new Date().toISOString();
    74|  const accountSid = readEnv('IVX_TWILIO_ACCOUNT_SID');
    75|  const authToken = readEnv('IVX_TWILIO_AUTH_TOKEN');
    76|  const apiKeySid = readEnv('IVX_TWILIO_API_KEY_SID');
    77|  const apiKeySecret = readEnv('IVX_TWILIO_API_KEY_SECRET');
    78|  const to = normalizePhoneToE164(input.to);
    79|  const from = resolveFrom();
    80|
    81|  const usingApiKey = Boolean(accountSid && apiKeySid && apiKeySecret);
    82|  const usingAuthToken = Boolean(accountSid && authToken && !usingApiKey);
    83|
    84|  const missingEnvNames: string[] = [];
    85|  if (!accountSid) missingEnvNames.push('IVX_TWILIO_ACCOUNT_SID');
    86|  if (!usingApiKey && !usingAuthToken) {
    87|    missingEnvNames.push('IVX_TWILIO_AUTH_TOKEN (or IVX_TWILIO_API_KEY_SID + IVX_TWILIO_API_KEY_SECRET)');
    88|  }
    89|  if (!from.messagingServiceSid && !from.fromPhone) missingEnvNames.push('IVX_TWILIO_MESSAGING_SERVICE_SID or IVX_TWILIO_FROM_PHONE');
    90|  if (!to) missingEnvNames.push('destination phone');
    91|
    92|  if (missingEnvNames.length > 0) {
    93|    return {
    94|      ok: false,
    95|      status: 'missing_config',
    96|      to: to || undefined,
    97|      missingEnvNames,
    98|      error: 'Twilio SMS is not fully configured. Need Account SID + either Auth Token or API Key SID/Secret.',
    99|      sentAt,
