   115|  body.set('To', to);
   116|  body.set('Body', input.message.slice(0, 1600));
   117|  if (from.messagingServiceSid) {
   118|    body.set('MessagingServiceSid', from.messagingServiceSid);
   119|  } else if (from.fromPhone) {
   120|    body.set('From', from.fromPhone);
   121|  }
   122|
   123|  const username = usingApiKey ? apiKeySid : accountSid;
   124|  const password = usingApiKey ? apiKeySecret : authToken;
   125|  const credentials = Buffer.from(`${username}:${password}`).toString('base64');
   126|  const { host, provider } = resolveApiHost();
   127|  const url = `${host}/2010-04-01/Accounts/${accountSid}/Messages.json`;
