   133|        Authorization: `Basic ${credentials}`,
   134|        'Content-Type': 'application/x-www-form-urlencoded',
   135|      },
   136|      body: body.toString(),
   137|    });
   138|
   139|    const text = await response.text();
   140|    const json = response.ok ? (JSON.parse(text) as Record<string, unknown>) : null;
   141|
   142|    if (!response.ok) {
   143|      const parsed = (() => {
   144|        try { return JSON.parse(text) as { message?: string; code?: number | string }; }
   145|        catch { return null; }
   146|      })();
   147|      const errorMessage = parsed?.message ?? text.slice(0, 300) ?? `Twilio responded ${response.status}`;
   148|      const isRateLimit = response.status === 429 || /rate.*limit|too many/i.test(errorMessage);
   149|      return {
   150|        ok: false,
   151|        status: isRateLimit ? 'rate_limited' : 'failed',
   152|        to,
   153|        from: from.messagingServiceSid || from.fromPhone,
   154|        httpStatus: response.status,
   155|        missingEnvNames,
   156|        error: errorMessage,
   157|        sentAt,
   158|        provider,
   159|      };
   160|    }
   161|
   162|    return {
   163|      ok: true,
   164|      status: 'sent',
