# Search .rork/history for env var values that were previously bridged to Render
# Extract values WITHOUT printing them - pipe directly to Render API
python3 << 'PYEOF'
import json, re, os, urllib.request

history_dir = '/home/user/rork-app/.rork/history/main'
env_values = {}

# Search for env var values in history files
# Look for patterns that indicate actual env var values being pushed to Render
for fname in os.listdir(history_dir):
    if not fname.endswith('_assistant.json'):
        continue
    fpath = os.path.join(history_dir, fname)
    try:
        with open(fpath) as f:
            content = f.read()
        # Look for JSON key-value pairs in Render env var format
        # Pattern: {"key":"VAR_NAME","value":"ACTUAL_VALUE"}
        pairs = re.findall(r'\{"key":"([A-Z_]+)","value":"([^"]*)"\}', content)
        for key, value in pairs:
            if key not in env_values and value and len(value) > 3:
                env_values[key] = value
    except:
        pass

# Also search for bash export commands with env var values
for fname in os.listdir(history_dir):
    if not fname.endswith('_assistant.json'):
        continue
    fpath = os.path.join(history_dir, fname)
    try:
        with open(fpath) as f:
            content = f.read()
        # Look for export VAR="value" patterns
        exports = re.findall(r'export\s+([A-Z_]+)="([^"]+)"', content)
        for key, value in exports:
            if key not in env_values and value and len(value) > 3:
                env_values[key] = value
    except:
        pass

print(f"Found {len(env_values)} unique env var values in history")
print(f"Keys found: {sorted(env_values.keys())}")

# Save to file for next step
with open('/tmp/ivx_env_values.json', 'w') as f:
    json.dump(env_values, f)
PYEOF

